		n++ // non-dividing lengths cover at most ceil(windowMillis/slideMillis) windows
	}
	// Never create windows with a negative start; clamp to the count of
	// window starts in [0,last] instead. Computing it this way also avoids
	// overflowing last/slideMillis + 1 when eventTime is near MaxInt64.
