// containingWindowCount returns how many windows contain eventTime. Windows
// start at 0, slideMillis, 2*slideMillis, ... and have length windowMillis;
// the last containing window starts at the greatest multiple of slideMillis
// not above eventTime, and at most ceil(windowMillis/slideMillis) windows
// reach back to it. Windows with a negative start are never created, so for
// early event times the count is just the number of starts in [0,last].
func (s *aggregateState) containingWindowCount(eventTime int64) int64 {
	last := eventTime - eventTime%s.slideMillis
	n := s.windowMillis / s.slideMillis
	if s.windowMillis%s.slideMillis != 0 {
		n++ // at most ceil(windowMillis/slideMillis) windows; this never overflows
	}
	// The true count is min(n, last/slideMillis+1). Compare against the
	// quotient directly so the +1 (which can reach MaxInt64+1 for slide 1
	// near MaxInt64) is never evaluated when it would leave the range.
	if q := last / s.slideMillis; q < n {
		n = q + 1
	}
	return n
}

// containingStart returns the start of the containing window reached back by
// offset indices from the last one (offset 0 = last window).
func (s *aggregateState) containingStart(eventTime, offset int64) int64 {
	last := eventTime - eventTime%s.slideMillis
	return last - offset*s.slideMillis
}

// firstOverflowingStart reports the start of the earliest containing window
// whose end (start + windowMillis) leaves the signed 64-bit range, or -1 when
// every containing window fits. Containing starts are an arithmetic sequence
// with step slideMillis, so overflow (if any) is a suffix; this computes its
// first member directly instead of walking the sequence.
func (s *aggregateState) firstOverflowingStart(eventTime int64) int64 {
	n := s.containingWindowCount(eventTime)
	lowest := s.containingStart(eventTime, n-1) // earliest containing start; never negative
	maxSafeStart := int64(math.MaxInt64 - s.windowMillis)
	if lowest > maxSafeStart {
		return lowest
	}
	safe := (maxSafeStart-lowest)/s.slideMillis + 1 // number of containing starts that fit
	if safe < n {
		// Reach back from last, which is at most eventTime, so the
		// subtraction cannot leave the signed 64-bit range.
		return s.containingStart(eventTime, n-1-safe)
	}
	return -1
}

