		`{"type":"event","key":"a","time":1200,"value":5}`,
		`{"type":"event","key":"a","time":1500,"value":7}`,
		`{"type":"watermark","time":2000}`,
	}, "\n")
	slidingOut, _, err := runSliding(t, input, 1000, 1000)
	if err != nil {
